from collections import Counter

def missing_tracks(planned, aired):
    """Return planned tracks that the play log does not confirm."""
    on_air = Counter((line.track, line.seconds) for line in aired)
    missing = []
    for track in planned:
        key = (track.id, track.seconds)
        if on_air[key] > 0:
            on_air[key] -= 1
        else:
            missing.append(track.id)
    return missing

