from collections import deque

def window_max(readings, k):
    candidates = deque()
    out = []
    for i, value in enumerate(readings):
        while candidates and readings[candidates[-1]] <= value:
            candidates.pop()
        candidates.append(i)
        if candidates[0] <= i - k:
            candidates.popleft()
        if i >= k - 1:
            out.append(readings[candidates[0]])
    return out

