def split(total, weights):
    whole = sum(weights)
    shares, rests = [], []
    for i, w in enumerate(weights):
        share, rest = divmod(total * w, whole)
        shares.append(share)
        rests.append((-rest, i))
    for _, i in sorted(rests)[: total - sum(shares)]:
        shares[i] += 1
    return shares

