public static bool[] Allow(int capacity, int rate, List<Request> requests)
{
    var tokens = new Dictionary<string, double>();
    var last = new Dictionary<string, long>();
    var result = new bool[requests.Count];
    for (var i = 0; i < requests.Count; i++)
    {
        var (at, client) = requests[i];
        var t = tokens.GetValueOrDefault(client, capacity);
        var since = at - last.GetValueOrDefault(client, at);
        t = t + since / 1000 * rate;
        last[client] = at;
        result[i] = t >= 1;
        tokens[client] = result[i] ? t - 1 : t;
    }
    return result;
}

