def slowest(lines, k):
    times = {}
    for line in lines:
        parts = line.split()
        if len(parts) != 4:
            continue
        method, path, status, ms = parts
        times.setdefault(f"{method} {path}", []).append(int(ms))
    medians = {e: sorted(t)[len(t) // 2] for e, t in times.items()}
    return sorted(medians, key=lambda e: -medians[e])[:k]

