export function fewestTiles(tiles, length) {
  const sorted = [...tiles].sort((a, b) => b - a)
  let left = length
  let count = 0
  for (const t of sorted) {
    count += Math.floor(left / t)
    left %= t
  }
  return left === 0 ? count : -1
}

