def close_scorebook(entries):
    seen = set()
    matches = {}
    tallies = {}
    for e in entries:
        key = (e.match, e.scorer, e.conceder, e.points)
        if key in seen:
            continue
        seen.add(key)
        m = matches.setdefault(e.match, 0)
        matches[e.match] = m + e.points - e.points
        tallies[e.scorer] = tallies.get(e.scorer, 0) + e.points
        tallies[e.conceder] = tallies.get(e.conceder, 0) - e.points
    inconsistent = [m for m, off in matches.items() if off != 0]
    return inconsistent, tallies
